const glossary:Record<string,{title:string;text:string}>={xg:{title:'Chansskapande · xG',text:'xG summerar modellens uppskattade målsannolikhet för varje oblockerat avslut. xG-andel visar hur stor del av lagens sammanlagda xG ditt lag skapat. 50 % är jämnt. Det är inte sannolikheten att vinna matchen.'},offense:{title:'Offensiv utdelning',text:'Gjorda mål minus xG i samma analysurval. Negativt värde innebär färre mål än modellen uppskattat. Det kan bero på avslutsskicklighet, motståndarens målvakt, variation och modellfel. Positiv utdelning är inte ett mått på hållbar prestation.'},defense:{title:'Defensivt målutfall',text:'xG emot minus insläppta mål i samma analysurval. Positivt värde innebär färre insläppta mål än modellen uppskattat. Målvakt, försvar, variation och modellfel påverkar. Detta är inte ett isolerat målvaktsbetyg.'},shooting:{title:'Skotteffektivitet · SH%',text:'Gjorda mål / skott på mål × 100. Ett lag med 3 mål på 30 skott har 10 % skotteffektivitet. Mål och skott avser samma spelform och matchurval som xG: ordinarie tid med båda målvakterna på isen. Hög effektivitet kan bero på chanskvalitet, avslutsskicklighet, motståndarens målvakt och variation. Jämför också gjorda mål med xG; skotteffektivitet är inget fristående bevis på överprestation. Saknade skottdata eller noll skott visas som —.'},corsi:{title:'Andel skottförsök · Corsi',text:'Lagets andel av alla skottförsök: mål, räddade, missade och blockerade. Ett mått på avslutsvolym, inte på chansernas kvalitet. Blockerade avslut ingår här men får inget xG i Under isens modell.'}};
function Picker({label,value,onChange,options,clubs=false}:{label:string;value:string;onChange:(v:string)=>void;options:{value:string;label:string}[];clubs?:boolean}){return <div className="picker"><label>{label}</label><Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label}>{clubs&&<ClubLogo team={value} size={24} decorative/>}<SelectValue>{options.find(o=>o.value===value)?.label||value}</SelectValue></SelectTrigger><SelectContent position="popper">{options.map(o=><SelectItem key={o.value} value={o.value}>{clubs&&<ClubLogo team={o.value} size={22} decorative/>}{o.label}</SelectItem>)}</SelectContent></Select></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><Layers size={30}/><h3>{title}</h3><p>{text}</p></div>}
function download(text:string,name:string,type:string){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exampleCsv(){return 'id;date;season;home;away;resultHome;resultAway;overtime;scope;gf;ga;xgf;xga;cf;ca;source;model\nEXEMPEL-ersatt-mig;2026-09-01;2026/27;Djurgårdens IF;Färjestad BK;1;3;false;all;1;2;2,4;1,7;42;36;EXEMPEL – byt till riktig källa;EXEMPEL – ange modell\n';}
function Metric({label,value,unit,note,rank,delta,children,onHelp,onExplore}:{label:string;value:string;unit?:string;note:string;rank?:number|null;delta?:number|null;children?:React.ReactNode;onHelp:()=>void;onExplore:()=>void}){return <article className="metric"><div className="metric-label"><span>{label}</span><HelpTooltip><TooltipTrigger asChild><button className="help-button" aria-label={`Förklara ${label}`} onClick={onHelp}><Info size={15}/></button></TooltipTrigger><TooltipContent>Vad betyder måttet?</TooltipContent></HelpTooltip></div><button className="metric-value" onClick={onExplore}>{value}<small>{unit}</small><ArrowUpRight size={19}/></button><p>{note}</p>{children}<div className="metric-foot">{rank!=null?<span><strong>#{rank}</strong> i urvalet</span>:<span>Analysurval</span>}{delta!=null?<span className="delta">{delta>0?<ArrowUp size={12}/>:delta<0?<ArrowDown size={12}/>:null}{sign(delta)} pp</span>:null}</div></article>}
function ComparisonBar({a,b,left,right,decimals=0}:{a:number;b:number;left:string;right:string;decimals?:number}){const widths=barWidths(a,b);return <div className="comparison"><div><strong>{fmt(a,decimals)}</strong><span>{right?`${left} / ${right}`:left}</span><strong>{fmt(b,decimals)}</strong></div><div className="bar-pair"><span style={{width:`${widths[0]}%`}}/><span style={{width:`${widths[1]}%`}}/></div></div>}
