 const dataset=mode==='demo'?DEMO:mode==='shl'?shlGames:saved;const seasons=[...new Set(dataset.map(g=>g.season))].sort().reverse(),models=[...new Set(dataset.map(g=>g.model))],activeModel=models.includes(model)?model:models[0];const current=dataset.filter(g=>g.season===season&&g.model===activeModel);const teamOptions=[...new Set(dataset.flatMap(g=>[g.home,g.away]))].sort((a,b)=>a.localeCompare(b,'sv'));const matches=teamGames(current,team,period,venue),usable=matches.filter(g=>perspective(g,team,scope)),total=aggregate(matches,team,scope),priorMatches=previousWindow(current,team,period,venue),prior=aggregate(priorMatches,team,scope);const league=teamOptions.map(t=>({team:t,...aggregate(teamGames(current,t,period,venue),t,scope)})).filter(t=>t.n);const ranks={shooting:ranking(league.map(t=>({team:t.team,value:t.shooting})),team),xg:ranking(league.map(t=>({team:t.team,value:t.share})),team),corsi:ranking(league.map(t=>({team:t.team,value:t.corsi})),team)};const previousComplete=period!=='all'&&prior.n===Number(period)&&total.n===Number(period),delta=previousComplete&&total.share!==null&&prior.share!==null?total.share-prior.share:null;const otherMatches=teamGames(current,second,period,venue),other=aggregate(otherMatches,second,scope);const wins=matches.filter(g=>result(g,team).win).length,points=matches.reduce((a,g)=>a+result(g,team).points,0),off=total.gf-total.xgf,def=total.xga-total.ga;const selected=dataset.find(g=>g.id===selectedId)||null;const matchTeam=selected&&![selected.home,selected.away].includes(team)?selected.home:team;
